/**
 * Named aliases over the generated OpenAPI schema.
 *
 * `schema.d.ts` is generated by `npm run generate:api` and must never be edited by
 * hand. Importing `components["schemas"]["EstimateOut"]` everywhere would be unreadable
 * and would couple every file to the generator's shape, so the whole surface is named
 * once here.
 *
 * Regenerate whenever the API's schemas change. If a rename lands, this file is where
 * the compiler will point.
 *
 * Reminder, because it is the easiest thing to get wrong: every `Decimal` field is a
 * **string** (`"1234.56"`). Route them through `domain/money.ts`.
 */
import type { components } from "./schema";

type Schemas = components["schemas"];

// ── Shared ──────────────────────────────────────────────────────────────────
export type ActorRef = Schemas["ActorRef"];
export type Ack = Schemas["Ack"];

// ── Users and auth ──────────────────────────────────────────────────────────
export type UserOut = Schemas["UserOut"];
export type UserUpdate = Schemas["UserUpdate"];
export type RoleUpdate = Schemas["RoleUpdate"];
export type SessionOut = Schemas["SessionOut"];
export type AccountStatusOut = Schemas["AccountStatusOut"];
export type ApprovalRequestOut = Schemas["ApprovalRequestOut"];
export type AvatarUploadRequest = Schemas["AvatarUploadRequest"];
export type AvatarUploadOut = Schemas["AvatarUploadOut"];
export type AvatarSaveRequest = Schemas["AvatarSaveRequest"];

// ── Estimates ───────────────────────────────────────────────────────────────
export type EstimateOut = Schemas["EstimateOut"];
export type EstimateCreate = Schemas["EstimateCreate"];
export type EstimateUpdate = Schemas["EstimateUpdate"];
export type EstimateTotalsOut = Schemas["EstimateTotalsOut"];
export type RoomTotalOut = Schemas["RoomTotalOut"];
export type TransitionRequest = Schemas["TransitionRequest"];
export type SubmitForReviewRequest = Schemas["SubmitForReviewRequest"];
export type SubmitForReviewOut = Schemas["SubmitForReviewOut"];

/** `Page[EstimateOut]` and friends are generated as distinct types per element. */
export type EstimatePage = Schemas["Page_EstimateOut_"];
export type ProjectPage = Schemas["Page_ProjectOut_"];

// ── Attachments ─────────────────────────────────────────────────────────────
export type AttachmentOut = Schemas["AttachmentOut"];
export type AttachmentCreate = Schemas["AttachmentCreate"];
export type UploadUrlRequest = Schemas["UploadUrlRequest"];
export type UploadUrlOut = Schemas["UploadUrlOut"];

// ── Projects ────────────────────────────────────────────────────────────────
export type ProjectOut = Schemas["ProjectOut"];
export type ProjectCreate = Schemas["ProjectCreate"];
export type ProjectUpdate = Schemas["ProjectUpdate"];
export type ProjectDetailOut = Schemas["ProjectDetailOut"];
export type WorkStatusUpdate = Schemas["WorkStatusUpdate"];
export type ProjectStatusUpdate = Schemas["ProjectStatusUpdate"];
export type MilestoneOut = Schemas["MilestoneOut"];
export type MilestoneCreate = Schemas["MilestoneCreate"];
export type MilestoneUpdate = Schemas["MilestoneUpdate"];
export type SupplementLinkOut = Schemas["SupplementLinkOut"];
export type SupplementLinkCreate = Schemas["SupplementLinkCreate"];
export type LinkedEstimate = Schemas["LinkedEstimate"];
export type ActivityOut = Schemas["ActivityOut"];
export type ClosingFormSubmit = Schemas["ClosingFormSubmit"];

// ── Meetings ────────────────────────────────────────────────────────────────
export type MeetingOut = Schemas["MeetingOut"];
export type MeetingCreate = Schemas["MeetingCreate"];
export type MeetingUpdate = Schemas["MeetingUpdate"];
export type AttendeeOut = Schemas["AttendeeOut"];

// ── AI ──────────────────────────────────────────────────────────────────────
export type ParseNotesRequest = Schemas["ParseNotesRequest"];
export type ParsedEstimate = Schemas["ParsedEstimate"];
export type ParsedRoom = Schemas["ParsedRoom"];
export type ParsedLineItem = Schemas["ParsedLineItem"];

// ── Public review ───────────────────────────────────────────────────────────
// Note these are snake_case (`unit_cost`), unlike the camelCase stored in `rooms`.
// They are a separate projection built server-side, not the same document.
export type ReviewEstimateOut = Schemas["ReviewEstimateOut"];
export type ReviewRoom = Schemas["ReviewRoom"];
export type ReviewLineItem = Schemas["ReviewLineItem"];
export type ReviewDecisionOut = Schemas["ReviewDecisionOut"];
export type RequestChangesRequest = Schemas["RequestChangesRequest"];
